const secretReference = 'PASTORAL_ID_HMAC_KEY';
const secret = $env[secretReference];
if (!secret) throw new Error('PASTORAL_ID_HMAC_KEY is required');

// 此草稿只接受 synthetic-user-a／synthetic-user-b 等合成識別，不接 LINE webhook。
// HMAC 輸出、原始合成識別與秘密值均不得輸出到 execution 結果。
return [{ json: {
  draftOnly: true,
  webhookConnected: false,
  identityAlgorithm: 'HMAC-SHA256',
  identityEncoding: 'base64url',
  identityVersion: 'hmac-sha256-v1',
  consentDefault: false,
  retentionDays: 30,
  maxHistoryItems: 10,
  serverSideIdentityFilterRequired: true,
  verifyEveryItemIdentity: true,
  onIdentityMismatch: 'block_and_safe_fallback',
  modelAllowedOnMismatch: false,
  secretConfigured: true
} }];
